package com.catpuzzle.assistant; import android.app.*;import android.content.*;import android.graphics.*;import android.hardware.display.*;import android.media.*;import android.media.projection.*;import android.os.*;import android.util.DisplayMetrics;import android.view.WindowManager;import java.nio.ByteBuffer; public class CaptureService extends Service{MediaProjection p;ImageReader r;VirtualDisplay d;long last; public void onCreate(){super.onCreate();if(Build.VERSION.SDK_INT>=26)getSystemService(NotificationManager.class).createNotificationChannel(new NotificationChannel("cap","Захват поля",NotificationManager.IMPORTANCE_LOW));startForeground(11,new Notification.Builder(this,Build.VERSION.SDK_INT>=26?"cap":"").setContentTitle("Cat Puzzle Assistant").setContentText("Локально считывает поле").setSmallIcon(android.R.drawable.ic_menu_camera).build());} public int onStartCommand(Intent i,int f,int id){if(p!=null)return START_STICKY;int code=i.getIntExtra("code",Activity.RESULT_CANCELED);Intent data=Build.VERSION.SDK_INT>=33?i.getParcelableExtra("data",Intent.class):(Intent)i.getParcelableExtra("data");if(data==null)return START_NOT_STICKY;p=((MediaProjectionManager)getSystemService(MEDIA_PROJECTION_SERVICE)).getMediaProjection(code,data);if(p==null)return START_NOT_STICKY;p.registerCallback(new MediaProjection.Callback(){public void onStop(){FrameStore.captureReady=false;stopSelf();}},new Handler(Looper.getMainLooper()));DisplayMetrics m=new DisplayMetrics();((WindowManager)getSystemService(WINDOW_SERVICE)).getDefaultDisplay().getRealMetrics(m);int w=m.widthPixels,h=m.heightPixels;r=ImageReader.newInstance(w,h,PixelFormat.RGBA_8888,2);r.setOnImageAvailableListener(x->{Image im=null;try{im=x.acquireLatestImage();if(im==null)return;long now=SystemClock.uptimeMillis();if(now-last<180)return;last=now;Image.Plane z=im.getPlanes()[0];ByteBuffer b=z.getBuffer();int ps=z.getPixelStride(),rs=z.getRowStride(),pad=rs-ps*w;Bitmap raw=Bitmap.createBitmap(w+pad/ps,h,Bitmap.Config.ARGB_8888);raw.copyPixelsFromBuffer(b);Bitmap cr=Bitmap.createBitmap(raw,0,0,w,h);raw.recycle();FrameStore.set(cr);}catch(Throwable t){}finally{if(im!=null)im.close();}},new Handler(Looper.getMainLooper()));d=p.createVirtualDisplay("CatPuzzle",w,h,m.densityDpi,DisplayManager.VIRTUAL_DISPLAY_FLAG_AUTO_MIRROR,r.getSurface(),null,null);FrameStore.captureReady=true;return START_STICKY;} public void onDestroy(){if(d!=null)d.release();if(r!=null)r.close();if(p!=null)p.stop();FrameStore.captureReady=false;super.onDestroy();} public android.os.IBinder onBind(Intent i){return null;}}